// Prepare for Twilio call
const item = $json;

// Format the phone number for Twilio (ensure it has country code)
let phoneNumber = item.Phone;
if (!phoneNumber.startsWith('+')) {
  // Assuming US numbers if no country code
  phoneNumber = '+1' + phoneNumber.replace(/[^0-9]/g, '');
}

item.formattedPhone = phoneNumber;

// Prepare basic call parameters
item.callParams = {
  to: item.formattedPhone,
  from: '+17752614880', // Replace with your Twilio phone number
  statusCallback: 'http://localhost:5678/webhook/twilio-status-callback', // Replace with your webhook URL
  statusCallbackEvent: ['initiated', 'ringing', 'answered', 'completed'],
  statusCallbackMethod: 'POST'
};

return item;

// Process VAPI call results
const item = $json;
const webhookData = $node['Wait for VAPI Callback'].json;

// Combine the original contact data with the webhook response
const result = {
  ...item,
  callCompleted: true,
  callTimestamp: new Date().toISOString(),
  callDuration: webhookData.call_duration || 0,
  callTranscript: webhookData.transcript || '',
  customerResponse: ''
};

// Analyze the transcript to determine customer interest
const transcript = result.callTranscript.toLowerCase();
if (transcript.includes('yes') || 
    transcript.includes('interested') || 
    transcript.includes('tell me more') || 
    transcript.includes('sounds good')) {
  result.customerResponse = 'Interested';
  result.callNotes = 'Customer expressed interest in our services.';
} else if (transcript.includes('no') || 
           transcript.includes('not interested') || 
           transcript.includes('busy')) {
  result.customerResponse = 'Not Interested';
  result.callNotes = 'Customer declined our services.';
} else {
  result.customerResponse = 'Unclear';
  result.callNotes = 'Customer response was unclear. Follow-up recommended.';
}

// Check if appointment was mentioned
if (transcript.includes('appointment') || 
    transcript.includes('schedule') || 
    transcript.includes('calendar') || 
    transcript.includes('calendly')) {
  result.appointmentBooked = true;

  // Determine appointment type preference
  if (transcript.includes('google') || transcript.includes('calendar')) {
    result.appointmentType = 'Google Calendar';
  } else if (transcript.includes('calendly')) {
    result.appointmentType = 'Calendly';
  } else {
    result.appointmentType = 'Google Calendar'; // Default
  }

  // Calculate a future date for the appointment (3 days in the future by default)
  const appointmentDate = new Date();
  appointmentDate.setDate(appointmentDate.getDate() + 3);
  result.appointmentDate = appointmentDate.toISOString();

  result.callNotes += ' Appointment requested.';
}

// Determine which service was offered based on the conversation
if (transcript.includes('appointment setting')) {
  result.serviceOffered = 'AI Appointment Setting';
} else if (transcript.includes('proposal')) {
  result.serviceOffered = 'AI Proposal Generator';
} else if (transcript.includes('marketing')) {
  result.serviceOffered = 'Digital Marketing';
} else {
  result.serviceOffered = 'AI Services Package';
}

return result;

// Process Twilio status callback
const data = $json;

// Log the call status
console.log('Twilio call status update:', data.CallStatus, 'for call SID:', data.CallSid);

// You can add logic here to handle different call statuses
// For example, you might want to update the Google Sheet with call status updates

return data;

// Process VAPI callback
const data = $json;

// Log the VAPI callback data
console.log('VAPI callback received for call:', data.call_id);

// You can add logic here to process the VAPI callback data
// This data will be passed to the Wait for VAPI Callback node

return data;

// Process the contact data from Google Sheets
const items = [];

// Assuming the Google Sheet has these columns:
// Name, Phone, Email, Address, Business Type, Google Maps Listing, Rankings, etc.
for (const row of $input.all()) {
  // Check if we have the necessary data
  if (!row.json.Phone) {
    continue; // Skip rows without phone numbers
  }

  // Create a new item with the contact data
  const item = {
    ...row.json,
    callCompleted: false,
    appointmentBooked: false,
    serviceOffered: '',
    callNotes: ''
  };

  items.push(item);
}

return items;

// In a real implementation, this would connect to Google Calendar API
// For demonstration purposes, we'll simulate the calendar integration

const item = $json;

if (item.appointmentType === 'Google Calendar') {
  // Prepare Google Calendar event details
  const eventDetails = {
    summary: `Discovery Call with ${item.Name}`,
    description: `Follow-up call to discuss ${item.serviceOffered} for ${item.Name}. Contact: ${item.Phone}, ${item.Email}`,
    start: {
      dateTime: item.appointmentDate,
      timeZone: 'America/New_York'
    },
    end: {
      dateTime: new Date(new Date(item.appointmentDate).getTime() + 30*60000).toISOString(), // 30 min meeting
      timeZone: 'America/New_York'
    },
    attendees: [
      {email: item.Email}
    ],
    reminders: {
      useDefault: false,
      overrides: [
        {method: 'email', minutes: 24 * 60}, // 1 day before
        {method: 'popup', minutes: 30} // 30 minutes before
      ]
    }
  };

  // In a real implementation, you would make an API call to Google Calendar here
  // For simulation purposes:
  item.calendarEventId = `gc-${Math.random().toString(36).substring(2, 15)}`;
  item.calendarLink = `https://calendar.google.com/calendar/event?eid=${item.calendarEventId}`;
  item.appointmentDetails = `Google Calendar appointment created for ${new Date(item.appointmentDate).toLocaleString()}`;
}

return item;

// In a real implementation, this would connect to Calendly API
// For demonstration purposes, we'll simulate the Calendly integration

const item = $json;

if (item.appointmentType === 'Calendly') {
  // Prepare Calendly event details
  const calendlyDetails = {
    event_type: 'discovery-call',
    invitee: {
      name: item.Name,
      email: item.Email,
      phone: item.Phone
    },
    questions_and_answers: {
      service_interest: item.serviceOffered
    }
  };

  // In a real implementation, you would make an API call to Calendly here
  // For simulation purposes:
  item.calendlyEventId = `cal-${Math.random().toString(36).substring(2, 15)}`;
  item.calendlyLink = `https://calendly.com/youraccount/discovery-call/${item.calendlyEventId}`;
  item.appointmentDetails = `Calendly appointment created for ${new Date(item.appointmentDate).toLocaleString()}`;
}

return item;
